using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;

    private HttpStatusCode replyStatus = HttpStatusCode.OK;
    private string replyBody = """{"status":"approved"}""";
    private string? receivedMethod;
    private string? receivedPath;
    private string? receivedContentType;
    private string? receivedBody;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"{baseAddress}");
        listener.Start();
        _ = Task.Run(ServeAsync);
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private async Task ServeAsync()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch { return; }

            receivedMethod = context.Request.HttpMethod;
            receivedPath = context.Request.Url!.AbsolutePath;
            receivedContentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                receivedBody = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(replyBody);
            context.Response.StatusCode = (int)replyStatus;
            context.Response.ContentType = "application/json";
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        var gateway = new HttpPaymentGateway(client);

        await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", receivedMethod);
        Assert.Equal("/v1/authorizations", receivedPath);
        Assert.StartsWith("application/json", receivedContentType);
        using var json = JsonDocument.Parse(receivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_back_as_approved()
    {
        replyBody = """{"status":"approved"}""";

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_is_read_back_as_declined()
    {
        replyBody = """{"status":"declined"}""";

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        replyBody = """{"id":"auth_1","status":"approved","risk":{"score":3}}""";

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_when_the_body_says_approved()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = """{"status":"approved"}""";

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_with_an_unparseable_body_is_still_a_decline()
    {
        replyStatus = HttpStatusCode.PaymentRequired;
        replyBody = "not json";

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.UnprocessableEntity)]
    [InlineData(HttpStatusCode.InternalServerError)]
    [InlineData(HttpStatusCode.ServiceUnavailable)]
    public async Task Other_error_statuses_are_raised_rather_than_treated_as_a_decision(HttpStatusCode status)
    {
        replyStatus = status;
        replyBody = """{"status":"approved"}""";

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);

        Assert.Equal(status, error.StatusCode);
    }

    [Theory]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{}""")]
    [InlineData("null")]
    public async Task Any_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        replyBody = body;

        var outcome = await Authorize();

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    [InlineData("""{"status":{"code":"approved"}}""")]
    public async Task A_malformed_answer_is_raised_rather_than_treated_as_a_decision(string body)
    {
        replyBody = body;

        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
